    #[test]
    fn execute_skipped_step_summary_shows_check_description() {
        let config = r#"
app_name: Test Project
steps:
  hello:
    command: echo hello
    completed_check:
      type: command_succeeds
      command: "exit 0"
workflows:
  default:
    steps: [hello]
"#;
        let temp = setup_project(config);
        let args = RunArgs::default();
        let cmd = RunCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        cmd.execute(&mut ui).unwrap();

        let summaries = ui.summaries();
        assert!(!summaries.is_empty());
        let step = &summaries[0].step_results[0];
        assert_eq!(step.status, StatusKind::Skipped);
        // Should show the check command, not "already complete"
        let detail = step.detail.as_deref().unwrap();
        assert!(
            detail.contains("exit 0"),
            "expected check description in summary detail, got: {}",
            detail
        );
    }

    #[test]
    fn resolve_steps_uses_template_for_brew() {
        let config_yaml = r#"
app_name: test
steps:
  brew:
    template: brew
workflows:
  default:
    steps: [brew]
"#;
        let temp = setup_project(config_yaml);
        let args = RunArgs::default();
        let cmd = RunCommand::new(temp.path(), args);

        let config = load_merged_config(temp.path()).unwrap();
        let steps = cmd.resolve_steps(&config, None).unwrap();

        let brew_step = steps.get("brew").unwrap();
        assert!(
            !brew_step.command.is_empty(),
            "template step should have a command from the brew template"
        );
        assert!(
            brew_step.command.contains("brew"),
            "brew template command should mention brew, got: {}",
            brew_step.command
        );
    }

