        step.after = vec!["echo post-deploy".to_string()];

        let mut steps = HashMap::new();
        steps.insert("deploy".to_string(), step);

        let runner = WorkflowRunner::new(&config, steps);
        let options = RunOptions {
            dry_run: true,
            ..Default::default()
        };
        let ctx = InterpolationContext::new();
        let mut ui = MockUI::new();

        runner
            .run_with_ui(
                &options,
                &ctx,
                &HashMap::new(),
                temp.path(),
                false,
                &HashMap::new(),
                None,
                &mut ui,
            )
            .unwrap();

        // Should show before and after hooks
        assert!(
            ui.messages().iter().any(|m| m.contains("before:") && m.contains("echo pre-deploy")),
            "expected before hook in messages, got: {:?}",
            ui.messages()
        );
        assert!(
            ui.messages().iter().any(|m| m.contains("after:") && m.contains("echo post-deploy")),
            "expected after hook in messages, got: {:?}",
            ui.messages()
        );
    }

    #[test]
    fn dry_run_ui_shows_env_vars() {
        let temp = TempDir::new().unwrap();

        let config: BivvyConfig = serde_yaml::from_str(
            r#"
            workflows:
              default:
                steps: [build]
        "#,
        )
        .unwrap();

        let mut step = make_step("build", "cargo build", vec![]);
        step.env
            .insert("RUST_LOG".to_string(), "debug".to_string());

        let mut steps = HashMap::new();
        steps.insert("build".to_string(), step);

        let runner = WorkflowRunner::new(&config, steps);
        let options = RunOptions {
            dry_run: true,
            ..Default::default()
        };
        let ctx = InterpolationContext::new();
        let mut ui = MockUI::new();

        runner
            .run_with_ui(
                &options,
                &ctx,
                &HashMap::new(),
                temp.path(),
                false,
                &HashMap::new(),
                None,
                &mut ui,
            )
            .unwrap();

        // Should show env vars
        assert!(
            ui.messages().iter().any(|m| m.contains("env:") && m.contains("RUST_LOG")),
            "expected env info in messages, got: {:?}",
            ui.messages()
        );
    }

    #[test]
    fn dry_run_ui_does_not_execute_commands() {
        let temp = TempDir::new().unwrap();
        let marker = temp.path().join("should_not_exist.txt");

        let config: BivvyConfig = serde_yaml::from_str(
            r#"
            workflows:
              default:
                steps: [danger]
        "#,
        )
        .unwrap();

        let mut steps = HashMap::new();
        steps.insert(
            "danger".to_string(),
            make_step("danger", &format!("touch {}", marker.display()), vec![]),
        );

        let runner = WorkflowRunner::new(&config, steps);
        let options = RunOptions {
            dry_run: true,
            ..Default::default()
        };
        let ctx = InterpolationContext::new();
        let mut ui = MockUI::new();

        let result = runner
            .run_with_ui(
                &options,
                &ctx,
                &HashMap::new(),
                temp.path(),
                false,
                &HashMap::new(),
                None,
                &mut ui,
            )
            .unwrap();

        assert!(result.success);
        assert!(!marker.exists(), "dry run should not create files");
    }

    #[test]
    fn dry_run_ui_skips_completed_check() {
        let temp = TempDir::new().unwrap();
        // Create the file that completed_check looks for
        fs::write(temp.path().join("done.txt"), "").unwrap();

        let config: BivvyConfig = serde_yaml::from_str(
            r#"
            workflows:
              default:
                steps: [task]
        "#,
        )
        .unwrap();

        let mut step = make_step("task", "echo hello", vec![]);
        step.completed_check = Some(crate::config::CompletedCheck::FileExists {
            path: "done.txt".to_string(),
        });

        let mut steps = HashMap::new();
        steps.insert("task".to_string(), step);

        let runner = WorkflowRunner::new(&config, steps);
        let options = RunOptions {
            dry_run: true,
            ..Default::default()
        };
        let ctx = InterpolationContext::new();
        let mut ui = MockUI::new();

        let result = runner
            .run_with_ui(
                &options,
                &ctx,
                &HashMap::new(),
                temp.path(),
                false,
                &HashMap::new(),
                None,
                &mut ui,
            )
            .unwrap();

        assert!(result.success);
        // In dry-run mode, should still show "Would run" even though step is complete
        assert!(
            ui.messages().iter().any(|m| m.contains("Would run")),
            "dry run should show command even when step is complete, got: {:?}",
            ui.messages()
        );
    }
}

