    /// Operation was skipped.
    Skipped,
    /// Operation has not been run yet.
    Pending,
    /// Operation is currently running.
    Running,
    /// Operation is blocked (dependency failed).
    Blocked,
    /// Non-fatal warning.
    Warning,
    /// Dry run preview (not executed).
    DryRun,
}

