                false,
                &HashMap::new(),
                None,
                &mut ui,
            )
            .unwrap();

        assert!(result.aborted);
        assert!(!result.success);
        // Only the failing step should have a result; next is blocked by abort
        assert_eq!(result.steps.len(), 1);
