        step.completed_check = Some(crate::config::CompletedCheck::FileExists {
            path: "done.txt".to_string(),
        });

        let mut steps = HashMap::new();
        steps.insert("task".to_string(), step);

        let runner = WorkflowRunner::new(&config, steps);
        let options = RunOptions {
            dry_run: true,
            ..Default::default()
        };
        let ctx = InterpolationContext::new();
        let mut ui = MockUI::new();

        let result = runner
            .run_with_ui(
                &options,
                &ctx,
                &HashMap::new(),
                temp.path(),
                false,
                &HashMap::new(),
                None,
                &mut ui,
            )
            .unwrap();

        assert!(result.success);
        // In dry-run mode, should still show "Would run" even though step is complete
        assert!(
